sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
layout(color) uniform half4 color;
float4 px(float2 p) { return float4(image.eval(p)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float a = float(c.a);
    float4 l = 4.0 * float4(c) - px(coord + float2(1, 0)) - px(coord + float2(-1, 0)) - px(coord + float2(0, 1)) - px(coord + float2(0, -1));
    float g = max(max(abs(l.r), abs(l.g)), max(abs(l.b), abs(l.a)));
    if (g * strength > 2.0) return half4(color.rgb * color.a, color.a);
    if (a <= 0.0) return half4(0.0);
    float3 p = min(floor(float3(c.rgb) / a * 7.0) / 6.0, float3(1.0));
    return half4(half3(p) * c.a, c.a);
}
